import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Every post's metadata, regenerated by scripts/sync-articles.js earlier in the
// same `npm run build` chain (see package.json), so it's always in sync with
// content/. Same source prerender.mjs derives its route list from, so the
// sitemap can't list a URL that wasn't prerendered (or vice versa).
const mdxMeta = JSON.parse(
  fs.readFileSync(path.join(__dirname, 'src/lib/generated/mdx-meta.json'), 'utf8')
);

// Generated by scripts/generate-beastlypedia-index.js, and read by prerender.mjs
// from the same file - so the sitemap cannot list a Beastfile that was never
// prerendered, which is exactly the drift the hand-mirrored lists below invite.
const beastlypedia = JSON.parse(
  fs.readFileSync(path.join(__dirname, 'src/lib/generated/beastlypedia-index.json'), 'utf8')
);

// The legal matrix, read by prerender.mjs from this same file, for the same
// reason as the two above: a hand-copied species list goes stale the moment a
// new animal is researched, and then the page exists but is never indexed.
const legalStatus = JSON.parse(
  fs.readFileSync(path.join(__dirname, 'src/lib/data/legalStatus.json'), 'utf8')
);

function parseFrontmatter(content) {
  // \r? - MDX files in this repo are a mix of LF and CRLF line endings;
  // an LF-only match silently drops frontmatter and the slug falls back
  // to the filename, putting wrong URLs in the sitemap.
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return {};
  const result = {};
  for (const line of match[1].split(/\r?\n/)) {
    const colonIdx = line.indexOf(':');
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const val = line.slice(colonIdx + 1).trim().replace(/^["']|["']$/g, '');
    result[key] = val;
  }
  return result;
}

// Mirrors slugify in src/lib/utils/slugify.js (incl. the "&"/"and" rule that
// makes "Small & Exotic Pets" produce "small-and-exotic-pets").
const slugifyCategory = (text) => text.toString().toLowerCase()
  .replace(/\s*&\s*|\s+and\s+/g, '-and-')
  .replace(/\s+/g, '-')
  .replace(/[^a-z0-9-]/g, '')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');

// Blog category slugs, one per category that actually has at least one post -
// Blog.jsx renders a pill for each of those and prerender.mjs prerenders them
// (see getMdxCategoryRoutes there), so they belong in the sitemap too.
// Excludes the two retired ones that 301 away (site-news, short-stories).
function getCategorySlugs() {
  const slugs = new Set();
  for (const post of mdxMeta) {
    // All categories the post is filed under, not just the primary one.
    const cats = (post.categories?.length ? post.categories : [post.category]).filter(Boolean);
    for (const cat of cats) {
      const slug = slugifyCategory(cat);
      if (!slug || slug === 'site-news' || slug === 'short-stories') continue;
      slugs.add(slug);
    }
  }
  return [...slugs];
}

// Chronicles series slug prefixes (mirrors CHRONICLES_SERIES in src/lib/chronicles.js).
// Their stories live at /chronicles/<id>/<part>/, not /blog/<slug>/.
const chroniclesPrefixes = { dex: 'chronicles-of-dex', otis: 'chronicles-of-otis' };
const isChroniclesSlug = (slug) =>
  Object.values(chroniclesPrefixes).some(prefix => slug.startsWith(prefix));

// mdx-meta.json carries the publish date but not `lastUpdated`, and lastmod
// should reflect the newer of the two when a post has been revised, so read it
// back out of the source file's frontmatter (post.path is repo-relative, e.g.
// "/content/guides/koi-cost-guide.mdx").
function readLastUpdated(post) {
  const filePath = path.join(__dirname, post.path);
  if (!fs.existsSync(filePath)) return null;
  return parseFrontmatter(fs.readFileSync(filePath, 'utf8')).lastUpdated || null;
}

// A post's date can be set ahead as a release date (see hasReachedPublishDate in
// public/_worker.js). The page itself stays in the sitemap either way, since it is
// deployed and we want it crawled, but a <lastmod> in the future is a bad signal:
// it claims the page changed on a day that has not happened. Drop it until then.
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const notInFuture = (date) => (date && String(date).slice(0, 10) <= today ? date : null);

function getMdxPosts() {
  // Short stories live on /chronicles/, not /blog/ (old URLs 301 in _redirects)
  return mdxMeta.filter(post => !isChroniclesSlug(post.slug)).map(post => ({
    path: `/blog/${post.slug}/`,
    // Only emit lastmod when the frontmatter carries a real, already-reached date - a
    // fabricated build-date lastmod is worse than none at all, and so is a future one.
    lastmod: notInFuture(readLastUpdated(post)) || notInFuture(post.date) || null,
    changefreq: 'weekly',
    priority: '0.7',
  }));
}

// /chronicles/<series>/ (landing list) + /chronicles/<series>/<n>/ per part.
// Part counts = the MDX short-story posts per series.
function getChroniclesPages() {
  const dedupedSlugs = [...new Set(mdxMeta.map(post => post.slug).filter(isChroniclesSlug))];

  const pages = [];
  for (const [id, prefix] of Object.entries(chroniclesPrefixes)) {
    const partCount = dedupedSlugs.filter(s => s.startsWith(prefix)).length;
    pages.push({ path: `/chronicles/${id}/`, changefreq: 'weekly', priority: '0.7' });
    for (let n = 1; n <= partCount; n++) {
      pages.push({ path: `/chronicles/${id}/${n}/`, changefreq: 'weekly', priority: '0.7' });
    }
  }
  return pages;
}

