async function generateSitemap() {
  console.log(`Building sitemap from ${mdxMeta.length} MDX post metadata entries...`);

  const chroniclesPages = getChroniclesPages();

  // Category and static pages carry no lastmod: stamping them with the build
  // date on every deploy makes the signal meaningless, and omitting lastmod
  // is valid per the sitemap spec.
  // short-stories is excluded: /blog/category/short-stories/ 301s to /chronicles/
  // /category/X/ is excluded entirely: it 301s to /blog/category/X/ (retired duplicate route)
  const blogCategoryPages = getCategorySlugs().map(slug => ({
    path: `/blog/category/${slug}/`,
    changefreq: 'weekly',
    priority: '0.7',
  }));

  const mdxPostPages = getMdxPosts();

  // Dedup static pages
  const uniqueStatic = [...new Set(staticPages)];

  let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
  xml += `<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n`;

  uniqueStatic.forEach(path => {
    const isHome = path === '/';
    const isHighFreq = ['/', '/facts/', '/blog/', '/encyclopedia/', '/guides/', '/animal-facts/', '/fact-files/', '/quiz/'].includes(path);
    const isGuideCat = path.startsWith('/guides/category/');
    const isGuideDetail = path.startsWith('/guides/') && !isGuideCat;
    const isEncAnimal = path.startsWith('/encyclopedia/animal/');
    const isEncCat = path.startsWith('/encyclopedia/category/');
    const isGearCat = path.startsWith('/gear/category/');
    const changefreq = isHighFreq ? 'weekly' : (isGuideDetail || isEncAnimal) ? 'monthly' : 'weekly';
    const priority = isHome ? '1.0' : isHighFreq ? '0.9' : (isEncCat || isGuideCat || isGearCat) ? '0.7' : (isGuideDetail || isEncAnimal) ? '0.6' : '0.7';
    xml += `  <url>\n`;
    xml += `    <loc>${BASE_URL}${path}</loc>\n`;
    xml += `    <changefreq>${changefreq}</changefreq>\n`;
    xml += `    <priority>${priority}</priority>\n`;
    xml += `  </url>\n`;
  });

  [...blogCategoryPages, ...mdxPostPages, ...chroniclesPages].forEach(page => {
    xml += `  <url>\n`;
    xml += `    <loc>${BASE_URL}${page.path}</loc>\n`;
    if (page.lastmod) xml += `    <lastmod>${page.lastmod}</lastmod>\n`;
    xml += `    <changefreq>${page.changefreq}</changefreq>\n`;
    xml += `    <priority>${page.priority}</priority>\n`;
    xml += `  </url>\n`;
  });

  xml += `</urlset>`;

  fs.writeFileSync('./dist/sitemap.xml', xml);
  console.log(`Sitemap written: ${uniqueStatic.length} static + ${blogCategoryPages.length} blog categories + ${mdxPostPages.length} MDX posts + ${chroniclesPages.length} chronicles`);
}

generateSitemap().catch(err => {
  console.error('Failed to generate sitemap:', err);
  process.exit(1);
});
